nter l’amortissement et comparer le pic de résonance.","difficulty":"challenge","llm_reads":["parameters","derived_values","measurements","student_actions"],"success_evidence":"réponse reliée à une loi"}],"misconceptions":[{"error":"La résonance se produit exactement à f₀ dans tous les cas.","remediation":"Observer le léger décalage dû à l’amortissement."},{"error":"L’amortissement change seulement l’amplitude.","remediation":"Comparer également largeur du pic et régime temporel."}],"differentiation":{"support":["Indice visuel sur le montage","Valeurs conseillées dans la simulation","Formule dévoilée seulement après un essai"],"extension":["Changer un seul paramètre à la fois","Justifier par unités et ordre de grandeur","Créer un contre-exemple"]},"exit_ticket":["Expression de f₀ du ressort ?","Condition de résonance ?","Effet d’un amortissement plus fort ?"],"teacher_audit":{"gaps_closed":["absence de manipulation authentique","cours trop textuel","résultats invisibles pour le tuteur IA"],"assessment_trace":["prédictions","mesures","tentatives","indices","validation"]}},"media_resources":[{"type":"image","url":"/media/images/physics/advanced_labs/oscillations_lab.webp","caption":"Photo scientifique générée : Systèmes mécaniques oscillants","trigger":"observe le montage réel","phase":"activation","metadata":{"source_type":"ai_generated_scientific_lab","visual":true,"alt":"Montage de Systèmes mécaniques oscillants","pedagogical_role":"observation et repérage"}},{"type":"simulation","url":"/media/simulations/physics/advanced/mechanics/?variant=oscillator","caption":"Oscillations et résonance — laboratoire interactif avancé","trigger":"manipule et mesure","phase":"exploration","metadata":{"simulation_id":"physics_mechanics_advanced_lab","simulation_version":"2.0","variant":"oscillator","llm_readable_state":true,"llm_controllable":true,"native_viewport":true,"commands":["start","set_variant","set_parameters","run_model","record_measurement","check","reset","reveal_hint","highlight"]}}]}},{"chapter_number":15,"title_fr":"Atome et quantification de l’énergie","title_ar":"الذرة وتكميم الطاقة","description_fr":"Niveaux d’énergie, transitions quantiques et spectres de raies.","description_ar":"الذرة وتكميم الطاقة","difficulty_level":"advanced","estimated_hours":2,"order_index":14,"lesson":{"title_fr":"Laboratoire guidé — Atome et quantification de l’énergie","title_ar":"الذرة وتكميم الطاقة","lesson_type":"theory","duration_minutes":100,"order_index":1,"learning_objectives":["Interpréter des niveaux d’énergie discrets","Relier transition, photon et longueur d’onde","Distinguer émission et absorption","Identifier un élément par son spectre"],"content":{"lesson_design":{"approach":"observer → prédire → manipuler → mesurer → expliquer","visual_first":true,"text_density":"low","student_autonomy":"guided_then_independent"},"official_alignment":{"level":"2e Bac Sciences Physiques BIOF","reference_weight":"Mécanique/atome — programme officiel","chapter_number":15},"guiding_question":"Pourquoi chaque élément possède-t-il une signature lumineuse unique ?","prerequisites":["onde lumineuse","énergie"],"learning_path":[{"step":1,"phase":"observer","student_action":"Explorer l’image réelle et nommer les éléments utiles.","evidence":"Deux observations précises."},{"step":2,"phase":"prédire","student_action":"Choisir deux transitions de Balmer et calculer leurs longueurs d’onde.","evidence":"Une prédiction justifiée avant le calcul."},{"step":3,"phase":"manipuler","student_action":"Associer longueur d’onde calculée et couleur observée.","evidence":"Au moins deux mesures enregistrées dans le laboratoire."},{"step":4,"phase":"expliquer","student_action":"Comparer le spectre de l’hydrogène au doublet du sodium.","evidence":"Une phrase causale reliant paramètre, graphe et loi."},{"step":5,"phase":"réinvestir","student_action":"Répondre au défi et au ticket de sortie sans indice.","evidence":"Deux réponses correctes sur trois."}],"micro_enseignements":[{"card":1,"title":"Quantification","idea":"L’électron n’occupe que certains niveaux d’énergie.","formula":"En discret","max_words":28},{"card":2,"title":"Photon","idea":"Une transition échange un photon d’énergie égale à l’écart.","formula":"|ΔE| = hν = hc/λ","max_words":28},{"card":3,"title":"Spectre de raies","idea":"Chaque atome possède des écarts d’énergie caractéristiques.","formula":"λ = hc/|ΔE|","max_words":28}],"phases":{"activation":{"duration_minutes":10,"mode":"image_hotspots","prompt":"Que vois-tu ? Quelle grandeur peut-on mesurer ?","resource":"image"},"exploration":{"duration_minutes":35,"mode":"advanced_simulation","rule":"Toute prédiction est faite avant le bouton Mesurer.","resource":"simulation"},"structuration":{"duration_minutes":25,"mode":"three_visual_cards","teacher_role":"Faire verbaliser la loi à partir des mesures."},"entrainement":{"duration_minutes":20,"mode":"interactive_challenges","feedback":"immédiat, ciblé, avec indice progressif"},"consolidation":{"duration_minutes":10,"mode":"exit_ticket","mastery_threshold":"2/3"}},"interactive_exercises":[{"id":"phys_ch15_i1","type":"predict_then_test","instruction":"Choisir deux transitions de Balmer et calculer leurs longueurs d’onde.","difficulty":"guided","llm_reads":["parameters","derived_values","measurements","student_actions"],"success_evidence":"réponse reliée à une loi"},{"id":"phys_ch15_i2","type":"parameter_hunt","instruction":"Associer longueur d’onde calculée et couleur observée.","difficulty":"guided","llm_reads":["parameters","derived_values","measurements","student_actions"],"success_evidence":"comparaison de mesures enregistrées"},{"id":"phys_ch15_i3","type":"explain_from_evidence","instruction":"Comparer le spectre de l’hydrogène au doublet du sodium.","difficulty":"challenge","llm_reads":["parameters","derived_values","measurements","student_actions"],"success_evidence":"réponse reliée à une loi"}],"misconceptions":[{"error":"L’électron peut avoir n’importe quelle énergie.","remediation":"Utiliser l’analogie d’un escalier et non d’une rampe."},{"error":"Une raie est une trajectoire d’électron.","remediation":"Relier la raie au photon émis lors d’une transition."}],"differentiation":{"support":["Indice visuel sur le montage","Valeurs conseillées dans la simulation","Formule dévoilée seulement après un essai"],"extension":["Changer un seul paramètre à la fois","Justifier par unités et ordre de grandeur","Créer un contre-exemple"]},"exit_ticket":["Relation entre ΔE et λ ?","Émission : niveau final plus haut ou plus bas ?","Pourquoi le spectre identifie-t-il l’atome ?"],"teacher_audit":{"gaps_closed":["absence de manipulation authentique","cours trop textuel","résultats invisibles pour le tuteur IA"],"assessment_trace":["prédictions","mesures","tentatives","indices","validation"]}},"media_resources":[{"type":"image","url":"/media/images/physics/advanced_labs/spectra_lab.webp","caption":"Photo scientifique générée : Atome et quantification de l’énergie","trigger":"observe le montage réel","phase":"activation","metadata":{"source_type":"ai_generated_scientific_lab","visual":true,"alt":"Montage de Atome et quantification de l’énergie","pedagogical_role":"observation et repérage"}},{"type":"simulation","url":"/media/simulations/physics/advanced/nuclear/?variant=spectra","caption":"Transitions et spectres — laboratoire interactif avancé","trigger":"manipule et mesure","phase":"exploration","metadata":{"simulation_id":"physics_nuclear_advanced_lab","simulation_version":"2.0","variant":"spectra","llm_readable_state":true,"llm_controllable":true,"native_viewport":true,"commands":["start","set_variant","set_parameters","run_model","record_measurement","check","reset","reveal_hint","highlight"]}}]}}]$physics_program$::jsonb)
    LOOP
        SELECT id INTO v_chapter_id
        FROM public.chapters
        WHERE subject_id = v_subject_id
          AND chapter_number = (spec->>'chapter_number')::integer
        ORDER BY id
        LIMIT 1;

        IF v_chapter_id IS NULL THEN
            RAISE EXCEPTION 'Chapitre de physique % introuvable', spec->>'chapter_number';
        END IF;

        UPDATE public.chapters
        SET title_fr = spec->>'title_fr',
            title_ar = spec->>'title_ar',
            description_fr = spec->>'description_fr',
            description_ar = spec->>'description_ar',
            difficulty_level = (spec->>'difficulty_level')::difficulty_level,
            estimated_hours = (spec->>'estimated_hours')::numeric,
            order_index = (spec->>'order_index')::integer
        WHERE id = v_chapter_id;

        lesson_spec := spec->'lesson';
        lesson_spec := jsonb_set(
            lesson_spec,
            '{media_resources}',
            (
                SELECT jsonb_agg(
                    CASE
                        WHEN media_item->>'type' = 'simulation' THEN jsonb_set(
                            media_item,
                            '{url}',
                            to_jsonb(replace(media_item->>'url', '/?variant=', '/index.html?variant=')::text)
                        )
                        ELSE media_item
                    END
                )
                FROM jsonb_array_elements(lesson_spec->'media_resources') AS media_item
            )
        );

        SELECT id INTO v_lesson_id
        FROM public.lessons
        WHERE chapter_id = v_chapter_id
        ORDER BY order_index, created_at, id
        LIMIT 1;

        IF v_lesson_id IS NULL THEN
            INSERT INTO public.lessons (
                chapter_id, title_fr, title_ar, lesson_type, content,
                learning_objectives, duration_minutes, order_index, media_resources
            ) VALUES (
                v_chapter_id,
                lesson_spec->>'title_fr',
                lesson_spec->>'title_ar',
                lesson_spec->>'lesson_type',
                lesson_spec->'content',
                lesson_spec->'learning_objectives',
                (lesson_spec->>'duration_minutes')::integer,
                (lesson_spec->>'order_index')::integer,
                lesson_spec->'media_resources'
            )
            RETURNING id INTO v_lesson_id;
        ELSE
            UPDATE public.lessons
            SET title_fr = lesson_spec->>'title_fr',
                title_ar = lesson_spec->>'title_ar',
                lesson_type = lesson_spec->>'lesson_type',
                content = lesson_spec->'content',
                learning_objectives = lesson_spec->'learning_objectives',
                duration_minutes = (lesson_spec->>'duration_minutes')::integer,
                order_index = (lesson_spec->>'order_index')::integer,
                media_resources = lesson_spec->'media_resources'
            WHERE id = v_lesson_id;
        END IF;

        resource_order := 0;
        FOR item IN
            SELECT value FROM jsonb_array_elements(lesson_spec->'media_resources')
        LOOP
            resource_order := resource_order + 1;
            resource_path := item->>'url';

            -- Renomme l’ancienne URL de dossier sans créer de doublon.
            UPDATE public.lesson_resources
            SET file_path = resource_path
            WHERE lesson_id = v_lesson_id
              AND file_path = replace(resource_path, '/index.html?variant=', '/?variant=')
              AND NOT EXISTS (
                  SELECT 1 FROM public.lesson_resources
                  WHERE lesson_id = v_lesson_id AND file_path = resource_path
              );

            IF EXISTS (
                SELECT 1 FROM public.lesson_resources
                WHERE lesson_id = v_lesson_id AND file_path = resource_path
            ) THEN
                UPDATE public.lesson_resources
                SET section_title = left(lesson_spec->>'title_fr', 200),
                    resource_type = item->>'type',
                    title = left(item->>'caption', 200),
                    description = item->>'caption',
                    trigger_text = left(coalesce(item->>'trigger', ''), 200),
                    phase = coalesce(
                        item->>'phase',
                        CASE WHEN item->>'type' = 'simulation' THEN 'exploration' ELSE 'activation' END
                    ),
                    difficulty_tier = (
                        CASE WHEN item->>'type' = 'simulation' THEN 'advanced' ELSE 'intermediate' END
                    )::difficulty_level,
                    concepts = jsonb_build_array('physique 2e BAC', spec->>'title_fr'),
                    metadata = coalesce(item->'metadata', '{}'::jsonb) || jsonb_build_object(
                        'visual', true,
                        'subject', 'Physique 2e BAC PC BIOF',
                        'chapter_number', (spec->>'chapter_number')::integer,
                        'source_type', CASE
                            WHEN item->>'type' = 'simulation' THEN 'interactive_scientific_lab'
                            ELSE 'ai_generated_scientific_lab'
                        END,
                        'state_contract', CASE
                            WHEN item->>'type' = 'simulation' THEN
                                jsonb_build_array(
                                    'parameters','derived_values','measurements','student_actions',
                                    'attempts','hints_used','completed_variants','objective_progress'
                                )
                            ELSE '[]'::jsonb
                        END
                    ),
                    order_index = resource_order
                WHERE lesson_id = v_lesson_id AND file_path = resource_path;
            ELSE
                INSERT INTO public.lesson_resources (
                    lesson_id, section_title, resource_type, title, description, file_path,
                    trigger_text, phase, difficulty_tier, concepts, metadata, order_index
                ) VALUES (
                    v_lesson_id,
                    left(lesson_spec->>'title_fr', 200),
                    item->>'type',
                    left(item->>'caption', 200),
                    item->>'caption',
                    resource_path,
                    left(coalesce(item->>'trigger', ''), 200),
                    coalesce(
                        item->>'phase',
                        CASE WHEN item->>'type' = 'simulation' THEN 'exploration' ELSE 'activation' END
                    ),
                    (
                        CASE WHEN item->>'type' = 'simulation' THEN 'advanced' ELSE 'intermediate' END
                    )::difficulty_level,
                    jsonb_build_array('physique 2e BAC', spec->>'title_fr'),
                    coalesce(item->'metadata', '{}'::jsonb) || jsonb_build_object(
                        'visual', true,
                        'subject', 'Physique 2e BAC PC BIOF',
                        'chapter_number', (spec->>'chapter_number')::integer,
                        'source_type', CASE
                            WHEN item->>'type' = 'simulation' THEN 'interactive_scientific_lab'
                            ELSE 'ai_generated_scientific_lab'
                        END,
                        'state_contract', CASE
                            WHEN item->>'type' = 'simulation' THEN
                                jsonb_build_array(
                                    'parameters','derived_values','measurements','student_actions',
                                    'attempts','hints_used','completed_variants','objective_progress'
                                )
                            ELSE '[]'::jsonb
                        END
                    ),
                    resource_order
                );
            END IF;
        END LOOP;
    END LOOP;
END
$migration$;

-- Libellés arabes détaillés (le JSON embarqué conserve aussi le titre arabe).
UPDATE public.chapters AS c
SET description_ar = v.description_ar
FROM (VALUES
    (1, 'انتشار اضطراب، سرعة الانتشار والتأخر الزمني.'),
    (2, 'الدور والتردد وطول الموجة وظاهرة الحيود.'),
    (3, 'حيود الضوء وتشتته ومعامل انكسار الوسط.'),
    (4, 'الاستقرار النووي وتحولات ألفا وبيتا وغاما وقانون التناقص.'),
    (5, 'نقص الكتلة وطاقة الربط والانشطار والاندماج.'),
    (6, 'شحن وتفريغ المكثف وثابت الزمن والطاقة الكهربائية.'),
    (7, 'التحريض الذاتي وتطور شدة التيار والطاقة المغناطيسية.'),
    (8, 'الأنظمة الحرة وشبه الدورية واللا دورية والحصيلة الطاقية.'),
    (9, 'نقل المعلومة وتضمين السعة وإزالة التضمين.'),
    (10, 'مرجع الدراسة وحصيلة القوى والقانون الثاني والطاقة الحركية.'),
    (11, 'السقوط بالاحتكاك والقذف وحركة جسيم مشحون في مجال مغناطيسي.'),
    (12, 'التجاذب الكوني والمدارات وقوانين كبلر والقمر الجغرافي الثابت.'),
    (13, 'الحركة الزاوية وعزم القصور وعزم القوة وطاقة الدوران.'),
    (14, 'التذبذبات الحرة والقسرية والخمود والتردد الخاص والرنين.'),
    (15, 'مستويات الطاقة والانتقالات الكمومية وأطياف الخطوط.')
) AS v(chapter_number, description_ar), public.subjects AS s
WHERE c.chapter_number = v.chapter_number
  AND s.id = c.subject_id
  AND lower(trim(s.name_fr)) = 'physique';

-- Contrôle final : 15 lignes, avec une leçon et au moins deux ressources par chapitre.
SELECT
    c.chapter_number,
    c.title_fr,
    count(DISTINCT l.id) AS lessons,
    count(lr.id) AS resources
FROM public.chapters c
JOIN public.subjects s ON s.id = c.subject_id
LEFT JOIN public.lessons l ON l.chapter_id = c.id
LEFT JOIN public.lesson_resources lr ON lr.lesson_id = l.id
WHERE lower(trim(s.name_fr)) = 'physique'
GROUP BY c.chapter_number, c.title_fr
ORDER BY c.chapter_number;
